import{_ as t,o as d,c as a,a0 as o}from"./chunks/framework.BGyYNsHo.js";const p=JSON.parse('{"title":"Cómo Ejecutar los Scripts, Benchmarks y Harnesses de Verificación","description":"","frontmatter":{},"headers":[],"relativePath":"es/how-to/04-scripts-y-benchmarks.md","filePath":"es/how-to/04-scripts-y-benchmarks.md"}'),r={name:"es/how-to/04-scripts-y-benchmarks.md"};function s(c,e,n,i,m,l){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="como-ejecutar-los-scripts-benchmarks-y-harnesses-de-verificacion" tabindex="-1">Cómo Ejecutar los Scripts, Benchmarks y Harnesses de Verificación <a class="header-anchor" href="#como-ejecutar-los-scripts-benchmarks-y-harnesses-de-verificacion" aria-label="Permalink to &quot;Cómo Ejecutar los Scripts, Benchmarks y Harnesses de Verificación&quot;">​</a></h1><p>Ejecuta los benchmarks basados en Node, las sondas y los harnesses de verificación que validan el motor OpenSWMM.</p><p>Todo se ejecuta desde la raíz del repo con <code>node scripts/&lt;nombre&gt;.mjs</code>. El patrón común: shim <code>globalThis.self/window</code>, cargar <code>public/swmm6wasm.js</code>, instanciar <code>swmm6wasm.wasm</code> en Node, y envolver la API C con <code>Module.cwrap</code>. Varios lanzan <code>server.py</code> y una instancia de Chrome vía CDP para pruebas de extremo a extremo.</p><h2 id="_1-benchmarks-y-sondas-motor-en-node" tabindex="-1">1. Benchmarks y sondas (motor en Node) <a class="header-anchor" href="#_1-benchmarks-y-sondas-motor-en-node" aria-label="Permalink to &quot;1. Benchmarks y sondas (motor en Node)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Propósito</th><th>Uso</th></tr></thead><tbody><tr><td><code>bench-1d-bellinge.mjs</code></td><td>Costos por-stride y por-ventana en el modelo Bellinge; proyecta 48 h de tiempo de pared</td><td>sin argumentos</td></tr><tr><td><code>bench-1d.mjs</code></td><td>Benchmark de stride 1D con salida JSON</td><td><code>node bench-1d.mjs &lt;inp&gt; [--wasm &lt;ruta&gt;] [--tag &lt;l&gt;] [--keep-vs]</code></td></tr><tr><td><code>probe-1d.mjs</code></td><td>Volcado de altura y profundidad de nodo por paso (máx. 80 pasos)</td><td><code>node probe-1d.mjs &lt;inp&gt;</code></td></tr><tr><td><code>probe-1d-nan.mjs</code></td><td>Corrida 1D completa de 48 h escaneando alturas/profundidades/volúmenes en busca de anomalías NaN/Inf</td><td><code>node probe-1d-nan.mjs [VS]</code></td></tr><tr><td><code>bench-wasm-threads.mjs</code></td><td><strong>Benchmark del motor con threads:</strong> ejecuta <code>simWorker.js</code> en Chrome aislado con THREADS 1 vs N; reporta tiempo y continuidad</td><td><code>node bench-wasm-threads.mjs [--inp &lt;p&gt;] [--threads 1,4] [--minutes &lt;n&gt;]</code></td></tr></tbody></table><h2 id="_2-harnesses-de-extremo-a-extremo-chrome-cdp-y-pruebas-unitarias" tabindex="-1">2. Harnesses de extremo a extremo Chrome/CDP y pruebas unitarias <a class="header-anchor" href="#_2-harnesses-de-extremo-a-extremo-chrome-cdp-y-pruebas-unitarias" aria-label="Permalink to &quot;2. Harnesses de extremo a extremo Chrome/CDP y pruebas unitarias&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Propósito</th><th>Puerto</th><th>Uso</th></tr></thead><tbody><tr><td><code>test-network3d.mjs</code></td><td>Suite de pruebas unitarias de geometría de red 3D (generación de polígonos, trazo de enlaces, features)</td><td>—</td><td><code>npm run test:3d</code></td></tr><tr><td><code>verify-bellinge.mjs</code></td><td><strong>Compuerta de verificación automatizada:</strong> Chrome headless carga la app, carga Bellinge Web, ejecuta la simulación con <code>simWorker.js</code> y verifica continuidad</td><td>CDP 9222</td><td>sin argumentos; escribe <code>scripts/verify-out/</code></td></tr><tr><td><code>verify-1d-split.mjs</code></td><td>Compuerta de regresión para la pierna de simulación 1D; verifica alturas finitas</td><td>—</td><td><code>node verify-1d-split.mjs &lt;inp&gt; [--wasm &lt;p&gt;] [--tol &lt;%&gt;] [--hours &lt;n&gt;] [--json]</code></td></tr><tr><td><code>verify-lchar.mjs</code></td><td>Verificación de longitud característica</td><td>—</td><td><code>node verify-lchar.mjs &lt;inp&gt;</code></td></tr></tbody></table>',7)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
